		res, ok := v.(*intakeinboxreads.RawJSONResponseMetadata)
		if !ok {
			return loomhttp.ErrInvalidType("intake_inbox_reads", "intake_detail", "*intakeinboxreads.RawJSONResponseMetadata", v)
		}
