// DecodeIntakeDetailRequest returns a decoder for requests sent to the
// intake_inbox_reads intake_detail endpoint.
func DecodeIntakeDetailRequest(mux loomhttp.Muxer, _ func(*http.Request) loomhttp.Decoder) func(*http.Request) (*intakeinboxreads.IntakeDetailPayload, error) {
	return func(r *http.Request) (*intakeinboxreads.IntakeDetailPayload, error) {
		var payload *intakeinboxreads.IntakeDetailPayload
		var err error
		var (
			slug      string
			projectID string
			pk        string
			sessionID *string

			params = mux.Vars(r)
		)
		slug = params["slug"]
		projectID = params["project_id"]
		err = loom.MergeErrors(err, loom.ValidateFormat("project_id", projectID, loom.FormatUUID))
		pk = params["pk"]
		err = loom.MergeErrors(err, loom.ValidateFormat("pk", pk, loom.FormatUUID))
		{
			c, cookieErr := r.Cookie("session-id")
			if cookieErr != nil && !errors.Is(cookieErr, http.ErrNoCookie) {
				return payload, cookieErr
			}
			var sessionIDRaw string
			sessionIDPresent := c != nil
			if sessionIDPresent {
				sessionIDRaw = c.Value
			}

			if sessionIDPresent {
				sessionID = &sessionIDRaw
			}
		}
		if err != nil {
			return payload, err
		}
		payload = NewIntakeDetailPayload(slug, projectID, pk, sessionID)

		return payload, nil
	}
}

